/** Format an amount in DOLLARS (not cents) as "$12.34". */
export function formatMoney(dollars: number): string {
  return `$${dollars.toFixed(2)}`;
}

export interface Order {
  id: string;
  /** Integer amount in cents, e.g. 1999 = $19.99 */
  totalCents: number;
}
